import{c as a,Q as e,j as n,m as t}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"The 6-File Claude Code Setup That Stops AI From Forgetting Your Project","description":"","frontmatter":{"url":"https://x.com/iiiichigo_chan/status/2081003533466317086","title":"The 6-File Claude Code Setup That Stops AI From Forgetting Your Project","author":"iiiichigo_chan","archived":"2026-07-30T00:00:00.000Z","handle":"@iiiichigo_chan","published":"2026-07-25T00:00:00.000Z","stats":"51 likes · 10 retweets · 81 bookmarks · 36188 views","tags":["claude-md","project-setup","verify-sh","skills","beginner"],"type":"twitter-article"},"headers":[],"relativePath":"research/tweets/2026-07-25-@iiiichigo_chan-317086.md","filePath":"research/tweets/2026-07-25-@iiiichigo_chan-317086.md","lastUpdated":1785909234000}'),p={name:"research/tweets/2026-07-25-@iiiichigo_chan-317086.md"};function i(o,s,r,l,c,d){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="the-6-file-claude-code-setup-that-stops-ai-from-forgetting-your-project-—-iiiichigo-chan" tabindex="-1">The 6-File Claude Code Setup That Stops AI From Forgetting Your Project — @iiiichigo_chan <a class="header-anchor" href="#the-6-file-claude-code-setup-that-stops-ai-from-forgetting-your-project-—-iiiichigo-chan" aria-label="Permalink to &quot;The 6-File Claude Code Setup That Stops AI From Forgetting Your Project — @iiiichigo_chan&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/iiiichigo_chan/status/2081003533466317086" target="_blank" rel="noreferrer">https://x.com/iiiichigo_chan/status/2081003533466317086</a><strong>作者</strong>：iiiichigo_chan（@iiiichigo_chan） <strong>發布日期</strong>：2026-07-25 <strong>收錄日期</strong>：2026-07-30 <strong>類型</strong>：Twitter Article <strong>統計</strong>：51 likes · 10 retweets · 81 bookmarks · 36188 views</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Most people use Claude Code like a smarter autocomplete.</p><p>They start a new session, explain the repo again, ask for a patch, lose context, then repeat it tomorrow.</p><p>The fix is not a longer prompt.</p><p>Your project needs a small operating system: a few files that tell the AI what it is building, how it works, and how to prove a change is safe.</p><p>Set this up once. Every future session gets better.</p><hr><h1 id="the-structure" tabindex="-1">The structure <a class="header-anchor" href="#the-structure" aria-label="Permalink to &quot;The structure&quot;">​</a></h1><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>your-project/</span></span>
<span class="line"><span>├── CLAUDE.md</span></span>
<span class="line"><span>├── docs/</span></span>
<span class="line"><span>│   ├── product.md</span></span>
<span class="line"><span>│   ├── architecture.md</span></span>
<span class="line"><span>│   └── decisions.md</span></span>
<span class="line"><span>├── tasks/</span></span>
<span class="line"><span>│   └── current.md</span></span>
<span class="line"><span>├── scripts/</span></span>
<span class="line"><span>│   └── verify.sh</span></span>
<span class="line"><span>└── .claude/</span></span>
<span class="line"><span>    └── skills/</span></span></code></pre></div><p>Just six files. No huge framework. No 200-page wiki.</p><hr><h1 id="_1-claude-md-is-the-front-door" tabindex="-1">1. CLAUDE.md is the front door <a class="header-anchor" href="#_1-claude-md-is-the-front-door" aria-label="Permalink to &quot;1. CLAUDE.md is the front door&quot;">​</a></h1><p>Claude Code loads project memory from CLAUDE.md.</p><p>This is where you put the rules that should apply every time: stack, commands, conventions, and things the AI must never touch.</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Project</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Stack</span></span>
<span class="line"><span>- Next.js, TypeScript, Postgres</span></span>
<span class="line"><span>- Package manager: pnpm</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Commands</span></span>
<span class="line"><span>- Run locally: pnpm dev</span></span>
<span class="line"><span>- Test: pnpm test</span></span>
<span class="line"><span>- Type check: pnpm typecheck</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Rules</span></span>
<span class="line"><span>- Reuse existing components before creating new ones</span></span>
<span class="line"><span>- Never change the database schema without a migration</span></span>
<span class="line"><span>- Add tests for bug fixes</span></span>
<span class="line"><span>- Do not edit files in /legacy without asking first</span></span></code></pre></div><p>Keep it short. Claude needs rules, not your company autobiography.</p><p>Official guide: <a href="https://docs.anthropic.com/en/docs/claude-code/memory" target="_blank" rel="noreferrer">https://docs.anthropic.com/en/docs/claude-code/memory</a></p><hr><h1 id="_2-product-md-tells-it-what-matters" tabindex="-1">2. product.md tells it what matters <a class="header-anchor" href="#_2-product-md-tells-it-what-matters" aria-label="Permalink to &quot;2. product.md tells it what matters&quot;">​</a></h1><p>Code explains how something works.</p><p>It rarely explains why it exists.</p><p>Write down the user, the job they are trying to do, and what the product should not become.</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Product</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## User</span></span>
<span class="line"><span>Independent designers who send proposals to clients.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Core job</span></span>
<span class="line"><span>Create, send, and track proposals without chasing spreadsheets.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Non-goals</span></span>
<span class="line"><span>- We are not a full CRM</span></span>
<span class="line"><span>- We do not manage invoices</span></span>
<span class="line"><span>- We optimize for speed, not endless customization</span></span></code></pre></div><p>This stops Claude from shipping technically correct features that pull the product in the wrong direction.</p><hr><h1 id="_3-architecture-md-prevents-random-rewrites" tabindex="-1">3. architecture.md prevents random rewrites <a class="header-anchor" href="#_3-architecture-md-prevents-random-rewrites" aria-label="Permalink to &quot;3. architecture.md prevents random rewrites&quot;">​</a></h1><p>This is the map of the repo.</p><p>Explain the important boundaries: where the API lives, where data flows, which services own what, and which folders are dangerous.</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Architecture</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- /app: UI and routes</span></span>
<span class="line"><span>- /lib: shared business logic</span></span>
<span class="line"><span>- /db: schema and queries</span></span>
<span class="line"><span>- /api: external integrations</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Data flow</span></span>
<span class="line"><span>UI -&gt; API route -&gt; service -&gt; database</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Important rule</span></span>
<span class="line"><span>Business logic belongs in /lib, not inside route handlers.</span></span></code></pre></div><p>You do not need to document every file.</p><p>Document the decisions a new engineer would otherwise learn the hard way.</p><hr><h1 id="_4-decisions-md-saves-the-expensive-context" tabindex="-1">4. decisions.md saves the expensive context <a class="header-anchor" href="#_4-decisions-md-saves-the-expensive-context" aria-label="Permalink to &quot;4. decisions.md saves the expensive context&quot;">​</a></h1><p>Every project accumulates weird choices.</p><p>Why did we use this provider? Why is this function ugly? Why can&#39;t we &quot;just switch&quot; a library?</p><p>Write down decisions once, so Claude does not reopen them every session.</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Decisions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 2026-07-25: Keep Stripe Checkout</span></span>
<span class="line"><span>We tested embedded payments, but Checkout had fewer edge cases</span></span>
<span class="line"><span>and works better on mobile.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## 2026-07-12: Use server-side search</span></span>
<span class="line"><span>Client-side filtering became slow after 10k records.</span></span></code></pre></div><p>Only log decisions that will matter later.</p><p>Do not turn this into a diary.</p><hr><h1 id="_5-current-md-gives-claude-one-job" tabindex="-1">5. current.md gives Claude one job <a class="header-anchor" href="#_5-current-md-gives-claude-one-job" aria-label="Permalink to &quot;5. current.md gives Claude one job&quot;">​</a></h1><p>AI agents get worse when every task feels equally important.</p><p>Before a session, write the current goal, constraints, and definition of done.</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Current task</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Goal</span></span>
<span class="line"><span>Add CSV export for proposal data.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Constraints</span></span>
<span class="line"><span>- Must work for 50k rows</span></span>
<span class="line"><span>- No new paid service</span></span>
<span class="line"><span>- Keep existing permissions</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Done when</span></span>
<span class="line"><span>- Export works from the dashboard</span></span>
<span class="line"><span>- Dates are formatted correctly</span></span>
<span class="line"><span>- Tests pass</span></span></code></pre></div><p>Now Claude has a target instead of a vague request like &quot;add export.&quot;</p><hr><h1 id="_6-verify-sh-is-the-part-most-people-skip" tabindex="-1">6. verify.sh is the part most people skip <a class="header-anchor" href="#_6-verify-sh-is-the-part-most-people-skip" aria-label="Permalink to &quot;6. verify.sh is the part most people skip&quot;">​</a></h1><p>The agent should not decide that its own work is correct.</p><p>Give it a repeatable verification command.</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#!/usr/bin/env bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pnpm lint</span></span>
<span class="line"><span>pnpm typecheck</span></span>
<span class="line"><span>pnpm test</span></span></code></pre></div><p>For bigger projects, add end-to-end tests, build checks, or a staging deploy preview.</p><p>The point is simple:</p><p>Claude can write the patch.</p><p>Your system needs to decide whether the patch passes.</p><hr><h1 id="add-skills-for-repeated-work" tabindex="-1">Add skills for repeated work <a class="header-anchor" href="#add-skills-for-repeated-work" aria-label="Permalink to &quot;Add skills for repeated work&quot;">​</a></h1><p>A skill is a reusable instruction set for a specific job.</p><p>Instead of re-explaining how your team writes release notes, reviews pull requests, generates PDFs, or tests a web app, put the workflow in a SKILL.md.</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>name: bug-fix</span></span>
<span class="line"><span>description: Use when fixing a reproducible bug.</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Reproduce the bug before changing code.</span></span>
<span class="line"><span>2. Find the smallest responsible surface.</span></span>
<span class="line"><span>3. Add a regression test.</span></span>
<span class="line"><span>4. Run the verification script.</span></span>
<span class="line"><span>5. Update decisions.md only if the fix changes an architectural choice.</span></span></code></pre></div><p>Anthropic&#39;s official skills repository includes examples for document creation, web testing, MCP building, brand guidelines, and more: <a href="https://github.com/anthropics/skills" target="_blank" rel="noreferrer">https://github.com/anthropics/skills</a></p><p>Skills docs: <a href="https://docs.anthropic.com/en/docs/claude-code/skills" target="_blank" rel="noreferrer">https://docs.anthropic.com/en/docs/claude-code/skills</a></p><hr><h1 id="the-workflow" tabindex="-1">The workflow <a class="header-anchor" href="#the-workflow" aria-label="Permalink to &quot;The workflow&quot;">​</a></h1><p>Once the files exist, start important tasks with this:</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Read CLAUDE.md, docs/product.md, docs/architecture.md,</span></span>
<span class="line"><span>docs/decisions.md, and tasks/current.md.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Before changing code, explain the plan and the test you will run.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>After the change, run scripts/verify.sh.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Only update decisions.md if we made a decision that will matter</span></span>
<span class="line"><span>for future work.</span></span></code></pre></div><p>That&#39;s it.</p><p>You are no longer hiring a new AI every morning.</p><p>You are giving the same system a project brief, a map, a task, and a way to check its own work.</p><p>Most people will keep asking Claude for snippets.</p><p>The useful setup is the one that lets it understand the project before it touches the code.</p><hr><p>If you like this article, bookmark it and follow @iiiichigo_chan</p><p>Thanks for reading.</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：入門級 Claude Code 專案架構——CLAUDE.md（規則）+ product.md（產品目的）+ architecture.md（架構地圖）+ decisions.md（決策紀錄）+ current.md（當前任務）+ verify.sh（機械驗證），加上 SKILL.md 承載可重複工作流。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ul><li>六個檔案分工：CLAUDE.md 是常駐規則（stack/commands/rules），product.md 說明「為什麼」（使用者/核心任務/non-goals），architecture.md 是倉庫地圖（邊界與危險資料夾），decisions.md 記錄「為什麼做這個選擇」避免每次重新討論，current.md 給單一明確任務目標與 Done-when，verify.sh 提供機械驗證命令（不讓 agent 自己判定成功）</li><li>核心原則：「agent 不該自己決定自己的工作是對的」，須有可重複執行的驗證命令</li><li>Skill 化重複工作：把「怎麼寫 release notes」「怎麼 review PR」等重複流程寫成 SKILL.md，附範例格式</li><li>建議的 session 起手式 prompt：讀五個檔案 → 動手前先講計畫與測試方式 → 改完跑 verify.sh → 只在決策真的重要時更新 decisions.md</li></ul><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>引用官方文件連結：<code>docs.anthropic.com/.../claude-code/memory</code>、<code>docs.anthropic.com/.../claude-code/skills</code>、<code>github.com/anthropics/skills</code></li><li>無實驗數據，純架構模板文章</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ul><li>本文的六檔案架構（CLAUDE.md/product/architecture/decisions/current/verify.sh + skills）是本 workspace 現有 <code>.claude/rules/*.md</code> + <code>.claude/refs/*.md</code> + <code>.claude/skills/*</code> + <code>memory/MEMORY.md</code> + <code>memory/LESSONS.md</code> 架構的<strong>簡化早期版本</strong>，本 workspace 已實作更成熟的四階層設計（auto-load rules / path-scoped / skills RESOLVER / memory episodic-first），本文對本 workspace 無新增資訊</li><li>「verify.sh 機械驗證」「agent 不自證成功」核心原則與本 workspace <code>core.md §TEST</code>（<code>unverified_success</code> 閘門、oracle 資格）方向一致但層次淺得多，僅提供 lint/typecheck/test 三行範例，無涉 oracle 資格檢驗、reward hacking 防線等進階內容</li><li>定位為給尚未建立任何專案結構的初學者的入門教學，適合作為對外分享的簡明範本，但對已有成熟 harness 的 workspace 邊際價值低</li></ul><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>3/10</td><td>Workspace 已有更成熟版本的同類架構，本文無新增資訊</td></tr><tr><td>B. 創新性 (20%)</td><td>3/10</td><td>基礎入門模板，無新穎觀點</td></tr><tr><td>C. 證據品質 (20%)</td><td>4/10</td><td>引用官方文件連結但無數據或案例佐證</td></tr><tr><td>D. 技術深度 (15%)</td><td>3/10</td><td>僅檔案模板，無深入機制說明</td></tr><tr><td>E. 泛化性 (15%)</td><td>6/10</td><td>適用任何剛起步、尚無專案架構的新專案</td></tr><tr><td><strong>加權總分</strong></td><td><strong>3.65/10</strong></td><td>A×0.3+B×0.2+C×0.2+D×0.15+E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Skip <strong>理由</strong>：入門級架構模板，本 workspace 已有更成熟的對應實作（rules/refs/skills/memory 四階層），無邊際新增價值，僅存檔備查。</p>`,89)])])}const m=a(p,[["render",i]]);export{u as __pageData,m as default};
